 "content": "def transform(grid):
    """Copy the highlighted shape into every all-zero matching footprint."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = next((v for v in counts if v not in (0, background)), None)
    if marker is None:
        return g
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker]
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(g[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    g[r+dr][c+dc] = marker
    return g
